class ProtegoRobotParser(RobotParser):
    def __init__(self, robotstxt_body: bytes, spider: Spider | None):
        from protego import Protego

        self.spider: Spider | None = spider
        body_decoded = decode_robotstxt(robotstxt_body, spider)
        self.rp = Protego.parse(body_decoded)

    @classmethod
    def from_crawler(cls, crawler: Crawler, robotstxt_body: bytes) -> Self:
        spider = None if not crawler else crawler.spider
        return cls(robotstxt_body, spider)

    def allowed(self, url: str | bytes, user_agent: str | bytes) -> bool:
        user_agent = to_unicode(user_agent)
        url = to_unicode(url)
        return self.rp.can_fetch(url, user_agent)

def parse(self, lines):
    """Parse the input lines from a robots.txt file.

    We allow that a user-agent: line is not preceded by
    one or more blank lines.
    """
    # states:
    #   0: start state
    #   1: saw user-agent line
    #   2: saw an allow or disallow line
    state = 0
    entry = Entry()

    self.modified()
    for line in lines:
        if not line:
            if state == 1:
                entry = Entry()
                state = 0
            elif state == 2:
                self._add_entry(entry)
                entry = Entry()
                state = 0
        # remove optional comment and strip line
        i = line.find('#')
        if i >= 0:
            line = line[:i]
        line = line.strip()
        if not line:
            continue
        line = line.split(':', 1)
        if len(line) == 2:
            line[0] = line[0].strip().lower()
            line[1] = urllib.parse.unquote(line[1].strip())
            if line[0] == "user-agent":
                if state == 2:
                    self._add_entry(entry)
                    entry = Entry()
                entry.useragents.append(line[1])
                state = 1
            elif line[0] == "disallow":
                if state != 0:
                    entry.rulelines.append(RuleLine(line[1], False))
                    state = 2
            elif line[0] == "allow":
                if state != 0:
                    entry.rulelines.append(RuleLine(line[1], True))
                    state = 2
            elif line[0] == "crawl-delay":
                if state != 0:
                    # before trying to convert to int we need to make
                    # sure that robots.txt has valid syntax otherwise
                    # it will crash
                    if line[1].strip().isdigit():
                        entry.delay = int(line[1])
                    state = 2
            elif line[0] == "request-rate":
                if state != 0:
                    numbers = line[1].split('/')
                    # check if all values are sane
                    if (len(numbers) == 2 and numbers[0].strip().isdigit()
                        and numbers[1].strip().isdigit()):
                        entry.req_rate = RequestRate(int(numbers[0]), int(numbers[1]))
                    state = 2
            elif line[0] == "sitemap":
                # According to http://www.sitemaps.org/protocol.html
                # "This directive is independent of the user-agent line,
                #  so it doesn't matter where you place it in your file."
                # Therefore we do not change the state of the parser.
                self.sitemaps.append(line[1])
    if state == 2:
        self._add_entry(entry)

def _add_entry(self, entry):
    if "*" in entry.useragents:
        # the default entry is considered last
        if self.default_entry is None:
            # the first default entry wins
            self.default_entry = entry
    else:
        self.entries.append(entry)

def can_fetch(self, useragent, url):
    """using the parsed robots.txt decide if useragent can fetch url"""
    if self.disallow_all:
        return False
    if self.allow_all:
        return True
    # Until the robots.txt file has been read or found not
    # to exist, we must assume that no url is allowable.
    # This prevents false positives when a user erroneously
    # calls can_fetch() before calling read().
    if not self.last_checked:
        return False
    # search for given user agent matches
    # the first match counts
    parsed_url = urllib.parse.urlparse(urllib.parse.unquote(url))
    url = urllib.parse.urlunparse(('','',parsed_url.path,
        parsed_url.params,parsed_url.query, parsed_url.fragment))
    url = urllib.parse.quote(url)
    if not url:
        url = "/"
    for entry in self.entries:
        if entry.applies_to(useragent):
            return entry.allowance(url)
    # try the default entry last
    if self.default_entry:
        return self.default_entry.allowance(url)
    # agent not found ==> access granted
    return True

def allowance(self, filename):
    """Preconditions:
    - our agent applies to this entry
    - filename is URL decoded"""
    for line in self.rulelines:
        if line.applies_to(filename):
            return line.allowance
    return True

class RuleLine:
    """A rule line is a single "Allow:" (allowance==True) or "Disallow:"
       (allowance==False) followed by a path."""
    def __init__(self, path, allowance):
        if path == '' and not allowance:
            # an empty value means allow all
            allowance = True
        path = urllib.parse.urlunparse(urllib.parse.urlparse(path))
        self.path = urllib.parse.quote(path)
        self.allowance = allowance

    def applies_to(self, filename):
        return self.path == "*" or filename[1:].startswith(self.path)

    def __str__(self):
        return ("Allow" if self.allowance else "Disallow") + ": " + self.path

